import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.B0p3fmqd.js";const i="/script-documentation/images/ammunation.jpg",p=JSON.parse('{"title":"Ammunation Management","description":"","frontmatter":{},"headers":[],"relativePath":"ammunation/index.md","filePath":"ammunation/index.md","lastUpdated":1791036569000}'),r={name:"ammunation/index.md"};function s(m,e,l,c,d,u){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="ammunation-management" tabindex="-1">Ammunation Management <a class="header-anchor" href="#ammunation-management" aria-label="Permalink to &quot;Ammunation Management&quot;">​</a></h1><p><img src="'+i+'" alt="Ammunation Management"></p><p>A player owned gun shop. Staff craft weapons and stock the shelf, and customers buy from the shop rep.</p><div class="info custom-block"><p class="custom-block-title">Version 5.0.1</p><p>Requires <code>community_bridge</code>, <code>ox_lib</code> and <code>oxmysql</code>. No custom inventory items are needed.</p></div><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><strong>Everything runs off the shop rep.</strong> Customers talk to him to buy gear. Staff also get Manage Stock for the shelf and prices, and Business Management for materials and stock runs.</li><li><strong>Crafting.</strong> Staff craft weapons, attachments and ammunition from materials the business buys through supplier contracts. Crafting earns experience and unlocks higher levels.</li><li><strong>Stock runs.</strong> Collect supplies from random collection points around the map.</li><li><strong>Categories.</strong> Each file in <code>shared/categories</code> is one category, and new files appear in game with no other change.</li><li><strong>Admin tools.</strong> Place everything in game with <code>/ammucreator</code>.</li></ul><h2 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h2><ol><li><a href="/script-documentation/ammunation/installation">Install the script</a></li><li><a href="/script-documentation/ammunation/configuration">Configure it</a></li></ol>',8)])])}const g=a(r,[["render",s]]);export{p as __pageData,g as default};
